import os, re, math, glob

base = '/filesystem/final_batch4__electrical_task8_electrical_specs__blind'
with open(os.path.join(base, '50_bim/BLDG4410-E_RevC.ifc')) as f:
    ifc_lines = f.read().splitlines()

entities = {}
for line in ifc_lines:
    m = re.match(r'^#(\d+)\s*=\s*([A-Z0-9_]+)\((.*)\);$', line.strip())
    if m:
        entities[int(m.group(1))] = (m.group(2), m.group(3))

# Parse cartesian points
points = {}
for eid, (etype, args) in entities.items():
    if etype == 'IFCCARTESIANPOINT':
        coords = [float(x) for x in re.findall(r'[-+]?\d*\.\d+|\d+', args)]
        points[eid] = coords

# Parse axis2placement3d
ax3d = {}
for eid, (etype, args) in entities.items():
    if etype == 'IFCAXIS2PLACEMENT3D':
        refs = [int(x) for x in re.findall(r'#(\d+)', args)]
        ax3d[eid] = points.get(refs[0], [0.0, 0.0, 0.0])

# Parse localplacement
loc_place = {}
for eid, (etype, args) in entities.items():
    if etype == 'IFCLOCALPLACEMENT':
        parts = args.split(',')
        parent = int(parts[0][1:]) if parts[0].strip().startswith('#') else None
        rel = int(parts[1][1:]) if parts[1].strip().startswith('#') else None
        loc_place[eid] = (parent, ax3d.get(rel, [0.0, 0.0, 0.0]))

def get_world_pos(lp_id):
    x, y, z = 0.0, 0.0, 0.0
    cur = lp_id
    while cur in loc_place:
        parent, (dx, dy, dz) = loc_place[cur]
        x += dx; y += dy; z += dz
        cur = parent
    return (x, y, z)

def get_local_z(lp_id):
    # height relative to parent (space or storey)
    if lp_id in loc_place:
        parent, (dx, dy, dz) = loc_place[lp_id]
        return dz, parent
    return 0.0, None

# Properties
prop_single = {}
for eid, (etype, args) in entities.items():
    if etype == 'IFCPROPERTYSINGLEVALUE':
        m = re.match(r"'([^']+)',\$,([A-Za-z0-9_]+)\((.*)\),\$$", args)
        if m:
            pname = m.group(1)
            val = m.group(3).strip("'")
            prop_single[eid] = (pname, val)

