import ifcopenshell, ifcopenshell.util.element, ifcopenshell.util.placement, numpy as np

ifc = ifcopenshell.open('50_bim/BLDG4410-E_RevC.ifc')

# Check CableCarrierSegments
by_ref = {}
for seg in ifc.by_type('IfcCableCarrierSegment'):
    psets = ifcopenshell.util.element.get_psets(seg)
    ref = psets.get('Pset_CableCarrierSegmentTypeCommon', {}).get('Reference')
    diam = psets.get('Pset_CableCarrierSegmentTypeConduitSegment', {}).get('NominalDiameter')
    # get length from representation or quantities
    qto = psets.get('Qto_CableCarrierSegmentBaseQuantities', {})
    # check representation extruded area solid depth
    depth = None
    if seg.Representation:
        for rep in seg.Representation.Representations:
            for item in rep.Items:
                if item.is_a('IfcExtrudedAreaSolid'):
                    depth = item.Depth
    by_ref.setdefault(ref, []).append((seg.Name, diam, depth, qto))

for ref, items in sorted(by_ref.items()):
    # group by run number (e.g. CND-MSB-1-1 -> run 1, seg 1)
    runs = {}
