        if 'NOT-ARMY' in opt or ('ARMY' not in opt):
            if tai.getparent() is not None: tai.getparent().remove(tai)
    print(f'================ {s} ================')
    def walk_spt(el, prefix):
        ttl = clean_text(el.find('TTL')) if el.find('TTL') is not None else ''
        print(f'{prefix} {ttl}')
