                if '[' in t:
                    print(f'    [{c.tag}] {t}')
        sub_i = 1
        for c in el.findall('SPT'):
            walk_spt(c, f'{prefix}.{sub_i}')
            sub_i += 1
    for pi, prt in enumerate(root.findall('.//PRT'), 1):
        print(f'PART {pi}')
        for si, spt in enumerate(prt.findall('SPT'), 1):
