        for m in re.finditer(r'\bSections?\s+(\d{2}\s+\d{2}\s+\d{2}(?:\.\d{2}(?:\s+\d{2})?)?)([^\w\s]?)', p.text, re.I):
            num = ' '.join(m.group(1).split())
            punct = m.group(2)
            if num not in allowed_26 or punct == ',':
                print(f'ERROR in {sec} P{i}: {m.group(0)!r} -> {p.text[max(0, m.start()-10):min(len(p.text), m.end()+40)]!r}')
        if '[' in p.text or ']' in p.text or '__' in p.text:
            print(f'BRACKET/BLANK in {sec} P{i}: {p.text}')
